import itertools, sys, time
import networkx as nx
import numpy as np

def h3_cayley():
    # Coxeter group H3 generated by reflections in R^3 (icosahedral); build by closure on unit vectors
    phi = (1 + 5 ** 0.5) / 2
    # simple roots of H3
    a1 = np.array([2.0, 0, 0]); a2 = np.array([-phi, 1.0, -1 / phi]); a3 = np.array([0, 0, 2.0])
    roots = [r / np.linalg.norm(r) for r in (a1, a2, a3)]
    refl = [np.eye(3) - 2 * np.outer(r, r) for r in roots]
    key = lambda M: tuple(np.round(M, 6).flatten())
    I = np.eye(3); seen = {key(I): I}; frontier = [I]
    while frontier:
        nf = []
        for M in frontier:
            for R in refl:
                N = R @ M
                k = key(N)
                if k not in seen:
                    seen[k] = N; nf.append(N)
        frontier = nf
    G = nx.Graph()
    for k, M in seen.items():
        for R in refl:
            G.add_edge(k, key(R @ M))
    return G

G = h3_cayley()
print("H3 Cayley graph:", G.number_of_nodes(), "vertices; planar", nx.check_planarity(G)[0], "bipartite", nx.is_bipartite(G), flush=True)
